From 66e3a6a6aba579c30cf039cf16bee59914950475 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 02:00:18 +0100
Subject: [PATCH] daemon: Wait a few seconds before warning about a battery
 drop

A dying battery can make UPower report 0% for an instant before going
back to its real level, and that was enough to show the critical battery
warning and start hibernating. Only warn if the drop lasts five seconds.

BUG: 518023
---
 daemon/powerdevilcore.cpp | 22 ++++++++++++++++++----
 daemon/powerdevilcore.h   |  2 ++
 2 files changed, 20 insertions(+), 4 deletions(-)

diff --git a/daemon/powerdevilcore.cpp b/daemon/powerdevilcore.cpp
index 33badced8..a7bd40596 100644
--- a/daemon/powerdevilcore.cpp
+++ b/daemon/powerdevilcore.cpp
@@ -56,6 +56,7 @@ Core::Core(QObject *parent)
     : QObject(parent)
     , m_hasDualGpu(false)
     , m_criticalBatteryTimer(new QTimer(this))
+    , m_batteryDropTimer(new QTimer(this))
     , m_activityConsumer(new KActivities::Consumer(this))
     , m_pendingWakeupEvent(true)
 {
@@ -182,6 +183,20 @@ void Core::onControllersReady()
     m_criticalBatteryTimer->setInterval(60000);
     connect(m_criticalBatteryTimer, &QTimer::timeout, this, &Core::onCriticalBatteryTimerExpired);

+    // Batteries can briefly report a bogus low level (e.g. a dying one reading 0%), so only warn if it lasts
+    m_batteryDropTimer->setSingleShot(true);
+    m_batteryDropTimer->setInterval(5000);
+    connect(m_batteryDropTimer, &QTimer::timeout, this, [this] {
+        const int currentPercent = currentChargePercent();
+        if (currentPercent < m_percentBeforeBatteryDrop) {
+            // When battery drains while still plugged in, warn nevertheless.
+            if (emitBatteryChargePercentNotification(currentPercent, m_percentBeforeBatteryDrop, QString(), ChargeNotificationFlag::NotifyWhenAcPluggedIn)) {
+                // Only refresh status if a notification has actually been emitted
+                loadProfile();
+            }
+        }
+    });
+
     // wait until the notification system is set up before firing notifications
     // to avoid them showing ontop of ksplash...
     if (QDBusConnection::sessionBus().interface()->isServiceRegistered(QStringLiteral("org.freedesktop.Notifications"))) {
@@ -759,10 +774,9 @@ void Core::onBatteryChargePercentChanged(int percent, const QString &udi)
     m_batteriesPercent[udi] = percent;

     if (currentPercent < previousPercent) {
-        // When battery drains while still plugged in, warn nevertheless.
-        if (emitBatteryChargePercentNotification(currentPercent, previousPercent, udi, ChargeNotificationFlag::NotifyWhenAcPluggedIn)) {
-            // Only refresh status if a notification has actually been emitted
-            loadProfile();
+        if (!m_batteryDropTimer->isActive()) {
+            m_percentBeforeBatteryDrop = previousPercent;
+            m_batteryDropTimer->start();
         }
     } else if (currentPercent > previousPercent) {
         updateBatteryNotifications(currentPercent);
diff --git a/daemon/powerdevilcore.h b/daemon/powerdevilcore.h
index 95c8341eb..67ff383c3 100644
--- a/daemon/powerdevilcore.h
+++ b/daemon/powerdevilcore.h
@@ -178,6 +178,8 @@ private:
     QPointer<KNotification> m_lowBatteryNotification;
     QTimer *const m_criticalBatteryTimer;
     QPointer<KNotification> m_criticalBatteryNotification;
+    QTimer *const m_batteryDropTimer;
+    int m_percentBeforeBatteryDrop = 0;
     QPointer<KNotification> m_powerCordPluggedInNotification;
     QPointer<KNotification> m_powerCordUnpluggedNotification;

-- 
